	private void captureProperty(String property) {
		previousProperties.put(property, System.getProperty(property));
	}

	private void restoreProperties() {
		previousProperties.forEach((property, value) -> {
			if (value == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, value);
			}
		});
		previousProperties.clear();
	}

	@Test
	public void datatypeHistogramCollapsesIntoRunCounting() throws ReflectiveOperationException {
		System.setProperty(NATIVE_ENGINE_PROPERTY, "true");
		System.setProperty(SYNOPSIS_PROPERTY, "true");
		Map<String, Long> expected = openMixedRepository(2000);

		long before = LmdbNativeDatatypeHistogram.RUNS.get();
		AtomicLong domainRuns = metric("ADJACENCY_DOMAIN_RUNS");
		AtomicLong summaryRuns = metric("ADJACENCY_DATATYPE_SUMMARY_RUNS");
		AtomicLong bulkHeaderBatches = metric("BULK_LITERAL_HEADER_BATCHES");
		AtomicLong scalarHeaderLookups = metric("SCALAR_LITERAL_HEADER_LOOKUPS");
		long domainBefore = domainRuns.get();
		long summaryBefore = summaryRuns.get();
		long bulkBefore = bulkHeaderBatches.get();
		long scalarBefore = scalarHeaderLookups.get();
		assertThat(histogram(DATATYPE_HISTOGRAM)).isEqualTo(expected);
		assertThat(LmdbNativeDatatypeHistogram.RUNS.get()).isGreaterThan(before);
		assertThat(domainRuns.get()).isGreaterThan(domainBefore);
		assertThat(summaryRuns.get()).isGreaterThan(summaryBefore);
		// New stores carry core datatype tags in non-inline literal IDs. The retained summary must consume those tags
		// directly; this workload contains no custom datatype that would require a legacy record-header batch.
		assertThat(bulkHeaderBatches.get()).isEqualTo(bulkBefore);
		assertThat(scalarHeaderLookups.get()).isEqualTo(scalarBefore);
	}

